typedef struct ring {
    uint8_t data[RING_CAPACITY];
    size_t head;
    size_t tail;
    size_t count;
} ring_t;

static void test_full_rejects(void) {
    ring_t r;
    ring_init(&r);
    for (int i = 0; i < RING_CAPACITY; i++) assert(ring_push(&r, (uint8_t)i) == 0);
    assert(ring_push(&r, 0) == -1);
    assert(ring_count(&r) == RING_CAPACITY);
}

void uart_init(uart_t *u, int port) {
    u->port = port;
    u->errors = 0;
    ring_init(&u->rx);
}

static void test_push_pop_order(void) {
    ring_t r;
    ring_init(&r);
    ring_push(&r, 1);
    ring_push(&r, 2);
    uint8_t b;
    assert(ring_pop(&r, &b) == 0 && b == 1);
    assert(ring_pop(&r, &b) == 0 && b == 2);
    assert(ring_pop(&r, &b) == -1);
}

int ring_pop(ring_t *r, uint8_t *byte) {
    if (r->count == 0) {
        return -1;
    }
    *byte = r->data[r->tail];
    r->tail = (r->tail + 1) % RING_CAPACITY;
    r->count--;
    return 0;
}

int ring_push(ring_t *r, uint8_t byte) {
    if (r->count == RING_CAPACITY) {
        return -1;
    }
    r->data[r->head] = byte;
    r->head = (r->head + 1) % RING_CAPACITY;
    r->count++;
    return 0;
}

int uart_poll(uart_t *u) {
    uint8_t b;
    int moved = 0;
    while (hal_get(u->port, &b) == 0) {
        if (ring_push(&u->rx, b) != 0) {
            u->errors++;
            break;
        }
        moved++;
    }
    return moved;
}

int uart_write(uart_t *u, const uint8_t *buf, size_t len) {
    for (size_t i = 0; i < len; i++) {
        if (hal_put(u->port, buf[i]) != 0) {
            u->errors++;
            return -1;
        }
    }
    return (int)len;
}
